//! `zig build fixtures` — the corpus's binary fixtures, built from the
//! format cores' own `Builder`s.
//!
//! Plan 09's rule for the format cores' unit tests is that a fixture is
//! BYTES A TEST WROTE, never a committed blob. The golden corpus is the
//! other half of that rule: a case needs the same bytes on every run of
//! every host, so the bytes ARE committed — and this file is where they
//! come from, so the diff that produced them is reviewable as Zig rather
//! than as a hex dump. `corpus/<case>/song.{mid,it}` is regenerated by
//! this verb and by nothing else; a `git diff` after it is the drift
//! showing, and the goldens' `(fixture … :sha256 …)` lines are what
//! makes that drift fail `zig build corpus` too.
//!
//! Every fixture goes through a `Builder` and the canonical writer, so
//! the committed bytes are a layout tempura itself produces and rung 1
//! (`write(read(bytes)) == bytes`) holds on them. Two exceptions, each
//! deliberate: they are the corpus's FOREIGN fixtures, the ones rung 2
//! exists for (plan 09), so each carries `(read)`, `(roundtrip)` and
//! `(write)`, and its golden pins `(rung1 :ok false)` as the fact it is
//! — the writer normalised the file, on purpose — beside a rung 2 that
//! has something to prove:
//!
//!   - `smf-smpte`: the canonical writer's division is ALWAYS pulses per
//!     quarter (plan 05), so the two division bytes of an otherwise
//!     canonical file are overwritten with the SMPTE spelling the writer
//!     will never emit. Nothing else about the file is hand-laid.
//!   - `it-patterns-masks`: it carries command bytes 27–31, which name
//!     no IT effect; the reader normalises them to "no effect" and the
//!     rewrite is therefore shorter than the original, on purpose.
//!
//! The walk corners are written with `:loose`, IT's row floor of 32
//! lifted: their patterns are two to six rows because the row map in the
//! golden is meant to be read beside plan 06's hand computations, and
//! the reader honours a short pattern with one warning the golden pins.
//!
//! This tool is a CONSUMER: it goes through the public `tempura` module
//! (as the CLI does), never through the sources, so a fixture that needs
//! a surface the module does not export fails here.

const std = @import("std");
const tempura = @import("tempura");

const smf = tempura.smf;
const itf = tempura.itf;

const Io = std.Io;
const Allocator = std.mem.Allocator;

/// `Cell.fx` is 1–26 for A–Z (ITTECH's `cmd = letter - '@'`).
const fx_a: u8 = 'A' - '@';
const fx_b: u8 = 'B' - '@';
const fx_c: u8 = 'C' - '@';
const fx_s: u8 = 'S' - '@';
const fx_t: u8 = 'T' - '@';

/// One committed fixture: which case directory it belongs to, what it is
/// called there, and the function that derives its bytes. `build` owns
/// nothing — the bytes come back in the caller's allocator.
const Case = struct {
    name: []const u8,
    file: []const u8,
    build: *const fn (Allocator) anyerror![]u8,
};

/// Every fixture the corpus carries, in case order. The `walk-*` corners
/// mirror plan 06's hand computations one for one, so a golden's row map
/// can be read beside the test that computed it.
const cases = [_]Case{
    .{ .name = "it-minimal", .file = "song.it", .build = itMinimal },
    .{ .name = "it-passthrough", .file = "song.it", .build = itPassthrough },
    .{ .name = "it-patterns-masks", .file = "song.it", .build = itPatternsMasks },
    .{ .name = "smf-format0", .file = "song.mid", .build = smfFormat0 },
    .{ .name = "smf-running-status", .file = "song.mid", .build = smfRunningStatus },
    .{ .name = "smf-smpte", .file = "song.mid", .build = smfSmpte },
    .{ .name = "smf-vlq-edges", .file = "song.mid", .build = smfVlqEdges },
    .{ .name = "skeleton-it", .file = "song.it", .build = skeletonIt },
    .{ .name = "skeleton-smf", .file = "song.mid", .build = skeletonSmf },
    .{ .name = "tempo-three-conductors-it", .file = "song.it", .build = threeConductorsIt },
    .{ .name = "tempo-three-conductors-smf", .file = "song.mid", .build = threeConductorsSmf },
    // The same bytes again, for the case whose document names them and
    // carries no inline dump: a by-reference conductor is timed by its
    // file, and the two spellings have to be reading ONE file for their
    // echo headers to be comparable at all.
    .{ .name = "tempo-by-reference-conductor", .file = "song.mid", .build = threeConductorsSmf },
    .{ .name = "walk-axx", .file = "song.it", .build = walkAxx },
    .{ .name = "walk-bxx", .file = "song.it", .build = walkBxx },
    .{ .name = "walk-constant", .file = "song.it", .build = walkConstant },
    .{ .name = "walk-cxx-past-end", .file = "song.it", .build = walkCxxPastEnd },
    .{ .name = "walk-cxx-sbx", .file = "song.it", .build = walkCxxSbx },
    .{ .name = "walk-runaway", .file = "song.it", .build = walkRunaway },
    .{ .name = "walk-s6x", .file = "song.it", .build = walkS6x },
    .{ .name = "walk-sdx", .file = "song.it", .build = walkSdx },
    .{ .name = "walk-sex", .file = "song.it", .build = walkSex },
    .{ .name = "walk-skip-end", .file = "song.it", .build = walkSkipEnd },
    .{ .name = "walk-t0x-slide", .file = "song.it", .build = walkT0xSlide },
    .{ .name = "walk-txx-memory", .file = "song.it", .build = walkTxxMemory },
    .{ .name = "residue-smf-exact", .file = "song.mid", .build = residueSmfExact },
    .{ .name = "residue-it-exact", .file = "song.it", .build = residueItExact },
    .{ .name = "residue-newer-version", .file = "song.it", .build = residueNewerVersion },
    .{ .name = "residue-corrupt", .file = "song.mid", .build = residueCorrupt },
    .{ .name = "residue-stale-lane", .file = "song.mid", .build = residueStaleLane },
    .{ .name = "residue-stale-conductor", .file = "song.mid", .build = residueStaleConductor },
    .{ .name = "residue-tail-only", .file = "song.it", .build = residueTailOnly },
    .{ .name = "edit-bound-smf-pair", .file = "x.mid", .build = boundSmfAnchor },
    .{ .name = "edit-bound-it-cell", .file = "x.it", .build = boundItAnchor },
};

pub fn main(init: std.process.Init) !u8 {
    const arena = init.arena.allocator();
    const gpa = init.gpa;
    const io = init.io;

    var stderr_buf: [4096]u8 = undefined;
    var stderr_file = Io.File.stderr();
    var stderr_writer = stderr_file.writer(io, &stderr_buf);
    const out = &stderr_writer.interface;
    defer out.flush() catch {};

    const args = try init.minimal.args.toSlice(arena);
    if (args.len != 2) {
        try out.print("usage: gen-fixtures <corpus-dir>\n", .{});
        return 2;
    }
    const root = args[1];

    for (cases) |c| {
        const bytes = c.build(gpa) catch |err| {
            try out.print("fixtures: {s}: cannot build {s}: {s}\n", .{ c.name, c.file, @errorName(err) });
            return 1;
        };
        defer gpa.free(bytes);

        const dir = try std.fs.path.join(arena, &.{ root, c.name });
        try Io.Dir.cwd().createDirPath(io, dir);
        const path = try std.fs.path.join(arena, &.{ dir, c.file });
        Io.Dir.cwd().writeFile(io, .{ .sub_path = path, .data = bytes }) catch |err| {
            try out.print("fixtures: {s}: cannot write {s}: {s}\n", .{ c.name, c.file, @errorName(err) });
            return 1;
        };
        try out.print("fixtures: {s}/{s}: {d} bytes\n", .{ c.name, c.file, bytes.len });
    }
    try out.print("fixtures: {d} written — `git diff` shows any drift\n", .{cases.len});
    return 0;
}

// ---------------------------------------------------------------------------
// The two finishers — a Builder in, committed bytes out
// ---------------------------------------------------------------------------

/// A fixture the writer would not stand behind is not a fixture: an
/// error-severity diagnostic from the canonical writer is a defect in
/// the case above, not something to commit.
const Error = error{FixtureWriterRefused};

fn finishSmf(gpa: Allocator, b: *smf.Builder, opts: smf.Options) ![]u8 {
    var seq = try b.finish();
    defer seq.deinit();
    var file = try smf.write(gpa, &seq, opts);
    defer file.deinit();
    if (file.diags.hasErrors()) return Error.FixtureWriterRefused;
    return gpa.dupe(u8, file.bytes);
}

fn finishIt(gpa: Allocator, b: *itf.Builder, source: ?[]const u8, opts: itf.write.Options) ![]u8 {
    var m = b.finish();
    defer m.deinit();
    var file = try itf.write.write(gpa, &m, source, opts);
    defer file.deinit();
    if (file.diags.hasErrors()) return Error.FixtureWriterRefused;
    return gpa.dupe(u8, file.bytes);
}

/// The walk corners' write options: IT's floor of 32 rows lifted, so a
/// four-row pattern stays four rows and its row map is the one plan 06
/// computed by hand.
const walk_opts: itf.write.Options = .{ .loose = true };

// ---------------------------------------------------------------------------
// The SMF fixtures
// ---------------------------------------------------------------------------

/// `smf-vlq-edges` — one track whose deltas are every width a variable-
/// length quantity has: 0 (one byte), 0x7F (the last one-byte value),
/// 0x80 (the first two-byte one) and 0x0FFF_FFFF (the largest a delta
/// may be at all, four bytes).
fn smfVlqEdges(gpa: Allocator) ![]u8 {
    var b: smf.Builder = .init(gpa);
    errdefer b.deinit();
    b.format = 0;
    b.division = .{ .ppq = 96 };

    const t = try b.addTrack();
    const at_7f: i64 = 0x7F;
    const at_80: i64 = at_7f + 0x80;
    const at_max: i64 = at_80 + 0x0FFF_FFFF;
    try b.addEvent(t, 0, .set_tempo, .{ .tempo = 500_000 });
    try b.addEvent(t, 0, .note_on, .{ .note = .{ .ch = 0, .key = 60, .vel = 100 } });
    try b.addEvent(t, at_7f, .note_off, .{ .note = .{ .ch = 0, .key = 60, .vel = 64 } });
    try b.addEvent(t, at_80, .note_on, .{ .note = .{ .ch = 0, .key = 62, .vel = 100 } });
    try b.addEvent(t, at_max, .note_off, .{ .note = .{ .ch = 0, .key = 62, .vel = 64 } });
    return finishSmf(gpa, &b, .{});
}

/// `smf-running-status` — three note-ons of one status, three note-offs
/// of another, a meta event that RESETS the status, and two control
/// changes after it. The writer's running-status rule and the reader's
/// are the same rule read twice.
fn smfRunningStatus(gpa: Allocator) ![]u8 {
    var b: smf.Builder = .init(gpa);
    errdefer b.deinit();
    b.format = 0;
    b.division = .{ .ppq = 96 };

    const t = try b.addTrack();
    try b.addEvent(t, 0, .note_on, .{ .note = .{ .ch = 0, .key = 60, .vel = 100 } });
    try b.addEvent(t, 0, .note_on, .{ .note = .{ .ch = 0, .key = 64, .vel = 100 } });
    try b.addEvent(t, 0, .note_on, .{ .note = .{ .ch = 0, .key = 67, .vel = 100 } });
    try b.addEvent(t, 96, .note_off, .{ .note = .{ .ch = 0, .key = 60, .vel = 64 } });
    try b.addEvent(t, 96, .note_off, .{ .note = .{ .ch = 0, .key = 64, .vel = 64 } });
    try b.addEvent(t, 96, .note_off, .{ .note = .{ .ch = 0, .key = 67, .vel = 64 } });
    const marker = try b.addBytes("verse");
    try b.addEvent(t, 96, .marker, .{ .bytes = marker });
    try b.addEvent(t, 96, .control_change, .{ .control = .{ .ch = 0, .num = 7, .val = 100 } });
    try b.addEvent(t, 96, .control_change, .{ .control = .{ .ch = 0, .num = 10, .val = 64 } });
    try b.addEvent(t, 192, .end_of_track, .empty);
    return finishSmf(gpa, &b, .{});
}

/// `smf-smpte` — a wall-clock file: 25 frames per second, 40 ticks per
/// frame, which OpenMPT's `frames · subframes / 2` reads as a 500-pulse
/// grid. Its `set-tempo` says 60 QPM and is kept and not believed: the
/// grid was derived at 120, so the writer and the bridge spell that
/// event as 500 000 µs on it (`Division.tempoOnGrid`), and the case's
/// rung 2 pins exactly that one payload moving. A 500 000 here would
/// pin nothing.
///
/// The canonical writer never emits a SMPTE division (plan 05), so the
/// file is written on the grid the conversion gives and its two division
/// bytes are then overwritten. That is the whole of the hand-laying:
/// every other byte is the writer's own — the tempo included, because
/// the rewrite is for a SMPTE sequence and this one is PPQ until its
/// header is patched.
fn smfSmpte(gpa: Allocator) ![]u8 {
    var b: smf.Builder = .init(gpa);
    errdefer b.deinit();
    b.format = 0;
    b.division = .{ .ppq = 500 };

    const t = try b.addTrack();
    const name = try b.addBytes("smpte");
    try b.addEvent(t, 0, .sequence_name, .{ .bytes = name });
    try b.addEvent(t, 0, .set_tempo, .{ .tempo = 1_000_000 });
    try b.addEvent(t, 0, .note_on, .{ .note = .{ .ch = 0, .key = 60, .vel = 100 } });
    try b.addEvent(t, 40, .note_off, .{ .note = .{ .ch = 0, .key = 60, .vel = 64 } });
    const bytes = try finishSmf(gpa, &b, .{});

    // `MThd` is tag(4) + length(4) + format(2) + ntrks(2) + division(2):
    // the division is bytes 12 and 13, and `E7 28` is 25 fps, 40 ticks.
    std.debug.assert(std.mem.eql(u8, bytes[0..4], "MThd"));
    bytes[12] = 0xE7;
    bytes[13] = 0x28;
    return bytes;
}

/// `smf-format0` — a format 1 file of three tracks: a conductor, and two
/// note tracks on different channels. `(write :format0 true)` merges
/// them, and the ties at tick 96 are what the stable sort is for.
fn smfFormat0(gpa: Allocator) ![]u8 {
    var b: smf.Builder = .init(gpa);
    errdefer b.deinit();
    b.format = 1;
    b.division = .{ .ppq = 96 };

    const conductor = try b.addTrack();
    const name = try b.addBytes("format0");
    try b.addEvent(conductor, 0, .sequence_name, .{ .bytes = name });
    try b.addEvent(conductor, 0, .time_signature, .{ .time_sig = .{ .nn = 4, .dd = 2, .cc = 24, .bb = 8 } });
    try b.addEvent(conductor, 0, .set_tempo, .{ .tempo = 500_000 });
    const marker = try b.addBytes("bar 2");
    try b.addEvent(conductor, 96, .marker, .{ .bytes = marker });
    try b.addEvent(conductor, 192, .end_of_track, .empty);

    const lead = try b.addTrack();
    try b.addEvent(lead, 0, .note_on, .{ .note = .{ .ch = 0, .key = 60, .vel = 100 } });
    try b.addEvent(lead, 96, .note_off, .{ .note = .{ .ch = 0, .key = 60, .vel = 64 } });
    try b.addEvent(lead, 96, .note_on, .{ .note = .{ .ch = 0, .key = 62, .vel = 100 } });
    try b.addEvent(lead, 192, .note_off, .{ .note = .{ .ch = 0, .key = 62, .vel = 64 } });

    const bass = try b.addTrack();
    try b.addEvent(bass, 48, .note_on, .{ .note = .{ .ch = 1, .key = 36, .vel = 90 } });
    try b.addEvent(bass, 144, .note_off, .{ .note = .{ .ch = 1, .key = 36, .vel = 64 } });
    return finishSmf(gpa, &b, .{});
}

/// `tempo-three-conductors-smf` — the file the case's `doc.sjon` is
/// arranged around, and whose timing tier that document carries inline.
///
/// Plan 03's three-segment map with the tempo on TRACK 2, which is the
/// midi set's rule that tempo on any track is honoured. Division 960
/// divides TPQ exactly (46 126 080 / 960 = 48 048), so SMF tick 960 is
/// 1q and 1920 is 2q with nothing to round.
///
/// The document's `(anchor …)` pins these bytes by `:size` and
/// `:sha256`, and `fromSjon` verifies them before the inline dump's
/// offsets are honoured — so a regeneration that changed one byte fails
/// `zig build corpus` with `anchor_mismatch` in the golden rather than
/// drifting quietly.
fn threeConductorsSmf(gpa: Allocator) ![]u8 {
    var b: smf.Builder = .init(gpa);
    errdefer b.deinit();
    b.format = 1;
    b.division = .{ .ppq = 960 };

    const conductor = try b.addTrack();
    const tempo = try b.addTrack();
    const name = try b.addBytes("conductor");
    try b.addEvent(conductor, 0, .sequence_name, .{ .bytes = name });
    try b.addEvent(conductor, 3840, .end_of_track, .empty);
    try b.addEvent(tempo, 0, .set_tempo, .{ .tempo = 480_000 });
    try b.addEvent(tempo, 960, .set_tempo, .{ .tempo = 400_000 });
    try b.addEvent(tempo, 1920, .set_tempo, .{ .tempo = 300_000 });
    try b.addEvent(tempo, 3840, .end_of_track, .empty);
    return finishSmf(gpa, &b, .{});
}

/// `skeleton-smf` — a file with no residue in it, which is what plan 04's
/// rule 1 derives a timeline from.
///
/// Everything rule 1 reads is here, and so is the line it draws. Track 2
/// sounds on channel 1 and moves controller 7 three times, so the
/// skeleton states a bound `notes` lane and a bound `curve` lane for it;
/// controller 10 is SET ONCE on the same channel and earns no lane at
/// all, because "more than one value" is the line between automation and
/// a setting. The pitch bend moves too. Track 1 is a conductor with a
/// name, a meter, a tempo and a marker — and the marker is a CUE.
fn skeletonSmf(gpa: Allocator) ![]u8 {
    var b: smf.Builder = .init(gpa);
    errdefer b.deinit();
    b.format = 1;
    b.division = .{ .ppq = 960 };

    const conductor = try b.addTrack();
    const name = try b.addBytes("skeleton");
    try b.addEvent(conductor, 0, .sequence_name, .{ .bytes = name });
    try b.addEvent(conductor, 0, .time_signature, .{ .time_sig = .{ .nn = 4, .dd = 2, .cc = 24, .bb = 8 } });
    try b.addEvent(conductor, 0, .set_tempo, .{ .tempo = 500_000 });
    const marker = try b.addBytes("bar 2");
    try b.addEvent(conductor, 3840, .marker, .{ .bytes = marker });
    try b.addEvent(conductor, 7680, .end_of_track, .empty);

    const lead = try b.addTrack();
    try b.addEvent(lead, 0, .control_change, .{ .control = .{ .ch = 0, .num = 7, .val = 64 } });
    try b.addEvent(lead, 0, .control_change, .{ .control = .{ .ch = 0, .num = 10, .val = 64 } });
    try b.addEvent(lead, 0, .note_on, .{ .note = .{ .ch = 0, .key = 60, .vel = 100 } });
    try b.addEvent(lead, 960, .control_change, .{ .control = .{ .ch = 0, .num = 7, .val = 96 } });
    try b.addEvent(lead, 1920, .note_off, .{ .note = .{ .ch = 0, .key = 60, .vel = 64 } });
    try b.addEvent(lead, 1920, .note_on, .{ .note = .{ .ch = 0, .key = 64, .vel = 100 } });
    try b.addEvent(lead, 2880, .pitch_bend, .{ .bend = .{ .ch = 0, .value = 9000 } });
    try b.addEvent(lead, 3840, .control_change, .{ .control = .{ .ch = 0, .num = 7, .val = 127 } });
    try b.addEvent(lead, 3840, .pitch_bend, .{ .bend = .{ .ch = 0, .value = 8192 } });
    try b.addEvent(lead, 3840, .note_off, .{ .note = .{ .ch = 0, .key = 64, .vel = 64 } });
    try b.addEvent(lead, 7680, .end_of_track, .empty);
    return finishSmf(gpa, &b, .{});
}

// ---------------------------------------------------------------------------
// The IT fixtures
// ---------------------------------------------------------------------------

/// `tempo-three-conductors-it` — the tracker twin, and the third of the
/// three spellings of one map.
///
/// Speed 6 and 24 ticks to the quarter make a row a 16th note, so row 4
/// is 1q and row 8 is 2q; `T96` sets the tempo to 150 and `TC8` to 200.
/// Pattern 1 is the one-row `B01` that jumps to itself, which is what
/// ends the walk with the state pattern 0 left behind — so the module
/// plays its two tempo changes ONCE. The highlight `[4 16]` is 16 rows
/// to the measure over 4 to the beat, which is the module's way of
/// spelling [4 4].
///
/// Written `:loose`, for the reason the walk corners are: the patterns
/// are 16 and 1 rows, under IT 2.14's floor of 32, because the row
/// arithmetic above is meant to be read rather than padded.
fn threeConductorsIt(gpa: Allocator) ![]u8 {
    var b: itf.Builder = .init(gpa);
    errdefer b.deinit();
    b.module.header.initial_speed = 6;
    b.module.header.initial_tempo = 125;
    b.module.header.highlight_minor = 4;
    b.module.header.highlight_major = 16;
    try b.addOrder(0);
    try b.addOrder(1);
    const song = try b.addPattern(16);
    song.at(4, 0).* = .{ .fx = fx_t, .param = 150 };
    song.at(8, 0).* = .{ .fx = fx_t, .param = 200 };
    const tail = try b.addPattern(1);
    tail.at(0, 0).* = .{ .fx = fx_b, .param = 1 };
    return finishIt(gpa, &b, null, .{ .loose = true });
}

/// `skeleton-it` — the tracker twin of `skeleton-smf`: a module with no
/// residue, which rule 1 reads for the addresses it uses.
///
/// Two channels sound, so two bound `notes` lanes; channel 1 also moves
/// its volume column, which is a bound `curve`. The pattern is 32 rows —
/// IT 2.14's own floor — so the file needs no `:loose` and rung 1 holds
/// on it under the strict clamps. The highlight `[4 16]` is 4 rows to the
/// beat and 16 to the measure, which is the module's way of saying
/// [4 4], and `T80` at row 16 is a tempo change the conductor picks up.
fn skeletonIt(gpa: Allocator) ![]u8 {
    var b: itf.Builder = .init(gpa);
    errdefer b.deinit();
    b.setTitle("skeleton");
    b.module.header.highlight_minor = 4;
    b.module.header.highlight_major = 16;
    try b.addOrder(0);
    const p = try b.addPattern(32);
    p.at(0, 0).* = .{ .note = 60, .ins = 1, .vol = 64 };
    p.at(0, 1).* = .{ .note = 36, .ins = 2 };
    p.at(8, 0).* = .{ .note = 64, .ins = 1, .vol = 48 };
    p.at(16, 0).* = .{ .note = 67, .ins = 1, .vol = 32, .fx = fx_t, .param = 0x80 };
    p.at(16, 1).* = .{ .note = 36, .ins = 2 };
    p.at(24, 0).* = .{ .note = itf.model.note_off };
    return finishIt(gpa, &b, null, .{});
}

/// `it-minimal` — one order, one 64-row pattern, one cell with all four
/// fields. The smallest module the canonical writer produces.
fn itMinimal(gpa: Allocator) ![]u8 {
    var b: itf.Builder = .init(gpa);
    errdefer b.deinit();
    b.setTitle("minimal");
    try b.addOrder(0);
    const p = try b.addPattern(64);
    p.at(0, 0).* = .{ .note = 60, .ins = 1, .vol = 64, .fx = fx_a, .param = 6 };
    p.at(0, 1).* = .{ .note = 48, .ins = 2 };
    p.at(32, 0).* = .{ .note = itf.model.note_off };
    try b.setMessage("a minimal module\rtempura");
    return finishIt(gpa, &b, null, .{});
}

/// `it-patterns-masks` — the pattern stream's own corners: a channel
/// that reuses its mask row after row, every family of the volume
/// column, and the command bytes 27–31, which sit inside ITTECH's range
/// and name no effect.
///
/// One of the two FOREIGN fixtures: those five commands read as NO
/// effect, so the rewrite is legitimately shorter than the original and
/// its golden pins `(rung1 :ok false)` beside the rung 2 that asserts
/// everything else survived (see the module header).
fn itPatternsMasks(gpa: Allocator) ![]u8 {
    var b: itf.Builder = .init(gpa);
    errdefer b.deinit();
    b.setTitle("masks");
    try b.addOrder(0);
    const p = try b.addPattern(32);

    // Channel 0: the same four fields with the same values, four rows
    // running. Row 0 sends every field, row 1 sends a mask of nothing
    // but repeat bits, and rows 2 and 3 reuse THAT mask — one lead byte
    // each, which is the whole point of the cache.
    for (0..4) |row| {
        p.at(row, 0).* = .{ .note = 60, .ins = 1, .vol = 64, .fx = fx_a, .param = 6 };
    }

    // Channel 1: one row per volume-column family, the raw byte as IT
    // stores it (it 04 §"Pattern unpacking": 0–64 volume, 65–124 the
    // slide families in tens, 128–192 pan, 193–202 tone porta, 203–212
    // vibrato). The mask never changes, so every row after the first is
    // a lead byte and a volume byte.
    const volumes = [_]u8{ 0, 64, 65, 75, 85, 95, 105, 115, 128, 192, 193, 202, 203, 212 };
    for (volumes, 0..) |vol, row| p.at(row, 1).* = .{ .vol = vol };

    // Channels 2–6: the command bytes ITTECH's range admits and no
    // letter names. The reader keeps the cell and drops the command,
    // with one `it_command_unknown` warning each.
    for (0..5) |i| {
        p.at(10 + i, 2 + i).* = .{ .fx = @intCast(27 + i), .param = @intCast(0x11 + i) };
    }
    return finishIt(gpa, &b, null, .{});
}

/// `it-passthrough` — one of everything the IT core never decodes: an
/// instrument body, three samples (PCM, IT215-compressed and ModPlug
/// ADPCM), a foreign trailing chunk and tempura's own `TMPU` payload.
///
/// Every opaque region is a slice of an ANCHOR the fixture builds first
/// — a `Module` plus the wrong bytes is nonsense (it 03, "The anchor") —
/// and the canonical writer copies them into the file it lays out.
fn itPassthrough(gpa: Allocator) ![]u8 {
    var anchor: std.ArrayList(u8) = .empty;
    defer anchor.deinit(gpa);

    // One 554-byte instrument record: `IMPI`, a name at 0x20, and 528
    // bytes nothing reads.
    const ins_at: u32 = @intCast(anchor.items.len);
    try anchor.appendSlice(gpa, "IMPI");
    try anchor.appendNTimes(gpa, 0, itf.model.ins.name - 4);
    try appendName(gpa, &anchor, "piano");
    try anchor.appendNTimes(gpa, 0xEE, itf.model.instrument_size - itf.model.ins.name - 26);

    // The three sample headers, each 80 bytes of `IMPS`. Their data
    // pointers are the writer's to patch, so they stay zero here.
    const pcm_hdr = try appendSampleHeader(gpa, &anchor, .{
        .name = "pcm",
        .flags = itf.model.sample_flag.has_data,
        .convert = itf.model.sample_convert.signed,
        .length = 8,
    });
    const it215_hdr = try appendSampleHeader(gpa, &anchor, .{
        .name = "squeezed",
        .flags = itf.model.sample_flag.has_data | itf.model.sample_flag.compressed,
        .convert = itf.model.sample_convert.signed | itf.model.sample_convert.delta,
        .length = 4,
    });
    const adpcm_hdr = try appendSampleHeader(gpa, &anchor, .{
        .name = "adpcm",
        .flags = itf.model.sample_flag.has_data,
        .convert = itf.model.sample_convert.adpcm,
        .length = 8,
    });

    // …and their data. Eight 8-bit frames is eight bytes; an IT215
    // block is a `u16` length and that many bytes; ModPlug's ADPCM is a
    // 16-byte nibble table then one nibble per frame.
    const pcm_data: u32 = @intCast(anchor.items.len);
    try anchor.appendSlice(gpa, &[_]u8{ 0x00, 0x10, 0x20, 0x30, 0x40, 0x30, 0x20, 0x10 });
    const it215_data: u32 = @intCast(anchor.items.len);
    try anchor.appendSlice(gpa, &[_]u8{ 0x06, 0x00, 0xA1, 0xA2, 0xA3, 0xA4, 0xA5, 0xA6 });
    const adpcm_data: u32 = @intCast(anchor.items.len);
    try anchor.appendNTimes(gpa, 0x7F, 16);
    try anchor.appendSlice(gpa, &[_]u8{ 0x12, 0x34, 0x56, 0x78 });

    // A trailing chunk another tracker wrote, kept verbatim and never
    // parsed, and tempura's residue payload after it.
    const foreign_at: u32 = @intCast(anchor.items.len);
    try anchor.appendSlice(gpa, "STPM");
    try anchor.appendSlice(gpa, &[_]u8{ 0x04, 0x00, 0x00, 0x00, 0xDE, 0xAD, 0xBE, 0xEF });
    const foreign_len: u32 = @intCast(anchor.items.len - foreign_at);
    const tmpu_at: u32 = @intCast(anchor.items.len);
    try anchor.appendSlice(gpa, "tempura residue");
    const tmpu_len: u32 = @intCast(anchor.items.len - tmpu_at);

    var b: itf.Builder = .init(gpa);
    errdefer b.deinit();
    b.setTitle("passthrough");
    b.module.header.flags |= itf.model.flag.instruments;
    try b.addOrder(0);
    const p = try b.addPattern(64);
    p.at(0, 0).* = .{ .note = 60, .ins = 1, .vol = 64 };
    p.at(16, 0).* = .{ .note = 62, .ins = 1 };
    try b.addInstrument("piano", .{ .off = ins_at, .len = itf.model.instrument_size });
    try b.addSample(.{
        .name = nameBytes("pcm"),
        .raw = .{ .off = pcm_hdr, .len = itf.model.sample_header_size },
        .data = .{ .off = pcm_data, .len = 8 },
        .bits = 8,
        .channels = 1,
        .enc = .pcm,
    });
    try b.addSample(.{
        .name = nameBytes("squeezed"),
        .raw = .{ .off = it215_hdr, .len = itf.model.sample_header_size },
        .data = .{ .off = it215_data, .len = 8 },
        .bits = 8,
        .channels = 1,
        .enc = .it215,
    });
    try b.addSample(.{
        .name = nameBytes("adpcm"),
        .raw = .{ .off = adpcm_hdr, .len = itf.model.sample_header_size },
        .data = .{ .off = adpcm_data, .len = 20 },
        .bits = 8,
        .channels = 1,
        .enc = .adpcm,
    });
    try b.addForeign("STPM".*, .{ .off = foreign_at, .len = foreign_len });
    b.module.tmpu = .{ .off = tmpu_at, .len = tmpu_len };
    return finishIt(gpa, &b, anchor.items, .{});
}

/// IT's name fields are left-justified, NUL-padded and 26 bytes.
fn nameBytes(name: []const u8) [26]u8 {
    var out: [26]u8 = @splat(0);
    itf.model.copyName(&out, name);
    return out;
}

fn appendName(gpa: Allocator, buf: *std.ArrayList(u8), name: []const u8) !void {
    const padded = nameBytes(name);
    try buf.appendSlice(gpa, &padded);
}

const SampleSpec = struct {
    name: []const u8,
    flags: u8,
    convert: u8,
    length: u32,
};

/// An 80-byte `IMPS` header at the end of `buf`, returning its offset.
/// Only the fields that give the data's extent and descriptor carry
/// anything; the rest is what IT writes for a plain sample.
fn appendSampleHeader(gpa: Allocator, buf: *std.ArrayList(u8), spec: SampleSpec) !u32 {
    const at: u32 = @intCast(buf.items.len);
    try buf.appendSlice(gpa, "IMPS");
    try buf.appendNTimes(gpa, 0, itf.model.smp.global_volume - 4);
    try buf.append(gpa, 64); // global volume
    try buf.append(gpa, spec.flags);
    try buf.append(gpa, 64); // default volume
    try appendName(gpa, buf, spec.name);
    try buf.append(gpa, spec.convert);
    try buf.append(gpa, 32); // default pan
    try appendDword(gpa, buf, spec.length);
    try appendDword(gpa, buf, 0); // loop begin
    try appendDword(gpa, buf, 0); // loop end
    try appendDword(gpa, buf, 8363); // C5 speed
    try appendDword(gpa, buf, 0); // sustain loop begin
    try appendDword(gpa, buf, 0); // sustain loop end
    try appendDword(gpa, buf, 0); // sample pointer — the writer's to patch
    try buf.appendNTimes(gpa, 0, 4); // auto-vibrato
    std.debug.assert(buf.items.len - at == itf.model.sample_header_size);
    return at;
}

fn appendDword(gpa: Allocator, buf: *std.ArrayList(u8), v: u32) !void {
    try buf.appendSlice(gpa, &std.mem.toBytes(std.mem.nativeToLittle(u32, v)));
}

// ---------------------------------------------------------------------------
// The walk corners — plan 06's hand computations, as files
// ---------------------------------------------------------------------------

/// Speed 6, tempo 125 (a fresh header), one order, four rows, one note:
/// four rows of six ticks and a song that loops at row 0.
fn walkConstant(gpa: Allocator) ![]u8 {
    var b: itf.Builder = .init(gpa);
    errdefer b.deinit();
    b.setTitle("walk-constant");
    try b.addOrder(0);
    const p = try b.addPattern(4);
    p.at(0, 0).* = .{ .note = 60 };
    return finishIt(gpa, &b, null, walk_opts);
}

/// `A03` shortens the row it sits on; `A00` keeps what it found, because
/// IT gives `Axx` no memory.
fn walkAxx(gpa: Allocator) ![]u8 {
    var b: itf.Builder = .init(gpa);
    errdefer b.deinit();
    b.setTitle("walk-axx");
    try b.addOrder(0);
    const p = try b.addPattern(4);
    p.at(2, 0).* = .{ .fx = fx_a, .param = 3 };
    p.at(3, 1).* = .{ .fx = fx_a, .param = 0 };
    return finishIt(gpa, &b, null, walk_opts);
}

/// `Txx` sets the tempo and `T00` recalls it — on its OWN channel only.
fn walkTxxMemory(gpa: Allocator) ![]u8 {
    var b: itf.Builder = .init(gpa);
    errdefer b.deinit();
    b.setTitle("walk-txx-memory");
    try b.addOrder(0);
    const p = try b.addPattern(6);
    p.at(1, 0).* = .{ .fx = fx_t, .param = 0x80 };
    p.at(2, 1).* = .{ .fx = fx_t, .param = 0x40 };
    p.at(3, 0).* = .{ .fx = fx_t, .param = 0x00 };
    p.at(4, 2).* = .{ .fx = fx_t, .param = 0x00 };
    return finishIt(gpa, &b, null, walk_opts);
}

/// `T0x` down and `T1x` up, one step per NON-row tick, each step its own
/// tempo segment.
fn walkT0xSlide(gpa: Allocator) ![]u8 {
    var b: itf.Builder = .init(gpa);
    errdefer b.deinit();
    b.setTitle("walk-t0x-slide");
    try b.addOrder(0);
    const p = try b.addPattern(2);
    p.at(0, 0).* = .{ .fx = fx_t, .param = 0x02 };
    p.at(1, 1).* = .{ .fx = fx_t, .param = 0x12 };
    return finishIt(gpa, &b, null, walk_opts);
}

/// `S6x` lengthens the row it sits on, and `S00` recalls the whole `Sxy`
/// its channel last saw.
fn walkS6x(gpa: Allocator) ![]u8 {
    var b: itf.Builder = .init(gpa);
    errdefer b.deinit();
    b.setTitle("walk-s6x");
    try b.addOrder(0);
    const p = try b.addPattern(4);
    p.at(0, 0).* = .{ .fx = fx_s, .param = 0x62 };
    p.at(2, 0).* = .{ .fx = fx_s, .param = 0x00 };
    p.at(3, 1).* = .{ .fx = fx_s, .param = 0x00 };
    return finishIt(gpa, &b, null, walk_opts);
}

/// `SEx` repeats the row without reprocessing its effects, and the
/// LEFTMOST `SEx` on the row is the one that counts.
fn walkSex(gpa: Allocator) ![]u8 {
    var b: itf.Builder = .init(gpa);
    errdefer b.deinit();
    b.setTitle("walk-sex");
    try b.addOrder(0);
    const p = try b.addPattern(3);
    p.at(0, 0).* = .{ .fx = fx_s, .param = 0x62 };
    p.at(0, 1).* = .{ .fx = fx_s, .param = 0xE1 };
    p.at(0, 2).* = .{ .note = 60 };
    p.at(0, 3).* = .{ .fx = fx_s, .param = 0xE3 };
    return finishIt(gpa, &b, null, walk_opts);
}

/// `Bxx` jumps to an order, forwards and backwards; the backward jump is
/// what makes the song a loop that never plays order 0 again.
fn walkBxx(gpa: Allocator) ![]u8 {
    var b: itf.Builder = .init(gpa);
    errdefer b.deinit();
    b.setTitle("walk-bxx");
    try b.addOrder(0);
    try b.addOrder(1);
    try b.addOrder(2);
    const p0 = try b.addPattern(2);
    _ = try b.addPattern(2);
    const p2 = try b.addPattern(2);
    p0.at(0, 0).* = .{ .fx = fx_b, .param = 2 };
    p2.at(0, 0).* = .{ .fx = fx_b, .param = 1 };
    return finishIt(gpa, &b, null, walk_opts);
}

/// A pattern loop in progress beats a `Cxx` on the same row; the break
/// is honoured the time round when there is no loop left to make.
fn walkCxxSbx(gpa: Allocator) ![]u8 {
    var b: itf.Builder = .init(gpa);
    errdefer b.deinit();
    b.setTitle("walk-cxx-sbx");
    try b.addOrder(0);
    try b.addOrder(1);
    const p0 = try b.addPattern(4);
    _ = try b.addPattern(4);
    p0.at(0, 0).* = .{ .fx = fx_s, .param = 0xB0 };
    p0.at(2, 0).* = .{ .fx = fx_s, .param = 0xB1 };
    p0.at(2, 1).* = .{ .fx = fx_c, .param = 2 };
    return finishIt(gpa, &b, null, walk_opts);
}

/// `SDx` delays a note inside its row; `SD0` delays by one, and a delay
/// as long as the row means the note never sounds.
fn walkSdx(gpa: Allocator) ![]u8 {
    var b: itf.Builder = .init(gpa);
    errdefer b.deinit();
    b.setTitle("walk-sdx");
    try b.addOrder(0);
    const p = try b.addPattern(2);
    p.at(0, 0).* = .{ .note = 60, .fx = fx_s, .param = 0xD3 };
    p.at(0, 1).* = .{ .note = 62, .fx = fx_s, .param = 0xD0 };
    p.at(0, 2).* = .{ .note = 64, .fx = fx_s, .param = 0xD6 };
    p.at(0, 3).* = .{ .note = 65 };
    return finishIt(gpa, &b, null, walk_opts);
}

/// `+++` plays nothing and the walk moves on; `---` is where the song
/// ends and loops, so the order after it never plays.
fn walkSkipEnd(gpa: Allocator) ![]u8 {
    var b: itf.Builder = .init(gpa);
    errdefer b.deinit();
    b.setTitle("walk-skip-end");
    try b.addOrder(0);
    try b.addOrder(itf.walk.order_skip);
    try b.addOrder(1);
    try b.addOrder(itf.walk.order_end);
    try b.addOrder(2);
    _ = try b.addPattern(2);
    _ = try b.addPattern(2);
    _ = try b.addPattern(2);
    return finishIt(gpa, &b, null, walk_opts);
}

/// Four rows a `(walk :max-rows 3)` never finishes: the cap trips
/// `walk_runaway` and the map stops where it stopped.
fn walkRunaway(gpa: Allocator) ![]u8 {
    var b: itf.Builder = .init(gpa);
    errdefer b.deinit();
    b.setTitle("walk-runaway");
    try b.addOrder(0);
    _ = try b.addPattern(4);
    return finishIt(gpa, &b, null, walk_opts);
}

/// The ruling: a `Cxx` whose row is past the TARGET pattern's end lands
/// on row 0 of that pattern, which is what IT and OpenMPT do — it does
/// not step on to the order after it.
fn walkCxxPastEnd(gpa: Allocator) ![]u8 {
    var b: itf.Builder = .init(gpa);
    errdefer b.deinit();
    b.setTitle("walk-cxx-past-end");
    try b.addOrder(0);
    try b.addOrder(1);
    const p0 = try b.addPattern(2);
    _ = try b.addPattern(2);
    p0.at(0, 0).* = .{ .fx = fx_c, .param = 5 };
    return finishIt(gpa, &b, null, walk_opts);
}

// ---------------------------------------------------------------------------
// The two bound-edit anchors — a file for a document that carries its dump
// ---------------------------------------------------------------------------
//
// Every `edit-bound-*` case is a document whose anchor carries its dump
// INLINE, which is what a bound operation acts on. The anchor still names
// a file, and plan 02 verifies that file's `:size` and `:sha256` before it
// honours a single offset — so a case with no file beside it loads with
// `anchor_unavailable`, and `tempura edit` used to refuse it outright.
//
// These two are the pair the CLI drives end to end: one SMF and one IT,
// each the canonical write of exactly the module its case's `doc.sjon`
// spells inline. The two documents carry these bytes' own `:size` and
// `:sha256`, so a change here needs one hand edit there — which is the
// point: the file and the dump are one thing said twice, and a drift
// between them should be loud.

/// `edit-bound-smf-pair/x.mid` — one format-0 track at 480 PPQ: three
/// notes on channel 1 and two controller events, the shape plan 07's SMF
/// pairing rules are exercised over.
fn boundSmfAnchor(gpa: Allocator) ![]u8 {
    var b: smf.Builder = .init(gpa);
    errdefer b.deinit();
    b.format = 0;
    b.division = .{ .ppq = 480 };

    const t = try b.addTrack();
    try b.addEvent(t, 0, .set_tempo, .{ .tempo = 500_000 });
    try b.addEvent(t, 0, .control_change, .{ .control = .{ .ch = 1, .num = 74, .val = 10 } });
    try b.addEvent(t, 0, .note_on, .{ .note = .{ .ch = 1, .key = 36, .vel = 100 } });
    try b.addEvent(t, 240, .note_off, .{ .note = .{ .ch = 1, .key = 36, .vel = 64 } });
    try b.addEvent(t, 480, .note_on, .{ .note = .{ .ch = 1, .key = 38, .vel = 90 } });
    try b.addEvent(t, 720, .note_off, .{ .note = .{ .ch = 1, .key = 38, .vel = 64 } });
    try b.addEvent(t, 960, .control_change, .{ .control = .{ .ch = 1, .num = 74, .val = 100 } });
    try b.addEvent(t, 960, .note_on, .{ .note = .{ .ch = 1, .key = 41, .vel = 80 } });
    try b.addEvent(t, 1200, .note_off, .{ .note = .{ .ch = 1, .key = 41, .vel = 64 } });
    try b.addEvent(t, 1920, .end_of_track, .empty);
    return finishSmf(gpa, &b, .{});
}

/// `edit-bound-it-cell/x.it` — three four-row patterns played by the
/// order list `0 1 2 2`, at speed 24 so a row is one quarter note
/// exactly. Written `:loose`, because IT's floor is 32 rows and the row
/// arithmetic the case is about should be readable rather than padded.
fn boundItAnchor(gpa: Allocator) ![]u8 {
    var b: itf.Builder = .init(gpa);
    errdefer b.deinit();
    b.setTitle("bound");
    b.module.header.initial_speed = 24;
    b.module.header.initial_tempo = 125;
    try b.addOrder(0);
    try b.addOrder(1);
    try b.addOrder(2);
    try b.addOrder(2);

    const p0 = try b.addPattern(4);
    p0.at(0, 0).* = .{ .note = 60, .ins = 1, .vol = 64, .fx = 'G' - '@', .param = 1 };
    p0.at(2, 0).* = .{ .note = 64, .ins = 1 };
    const p1 = try b.addPattern(4);
    p1.at(0, 0).* = .{ .note = 67, .ins = 1 };
    _ = try b.addPattern(4);
    return finishIt(gpa, &b, null, walk_opts);
}

// ---------------------------------------------------------------------------
// The residue fixtures — one file per rule of plan 04's reconciliation
// ---------------------------------------------------------------------------
//
// These five (in two kinds) are the only fixtures here that are not a
// `Builder` and a writer: a file that CARRIES a residue is one tempura
// built, and building it is `doc/pipeline.zig`'s whole chain. So the
// document below is rendered, packed, attached and written exactly as
// `tempura build` would write it — and then, for the rules that are
// about a file somebody else touched, the bytes are edited the way a DAW
// or a tracker would have edited them.
//
// Each mutation is the smallest one that reaches its rule, and each is
// spelled against the file rather than against a builder, because what
// the rule reacts to IS the file.

/// The document every residue fixture is built from: one native notes
/// lane over its own tempo and meter, so the file carries exactly one
/// lane record, one conductor record and one essence.
const residue_doc: [:0]const u8 =
    \\; residue — the corpus's reconciliation fixture
    \\(timeline :title "residue" :length 1bar)
    \\
    \\(tempo-point :at 0bar :qpm 120)
    \\(meter-point :at 0bar :sig [4 4])
    \\
    \\(lane :name kick :kind notes :target kick
    \\  (note :at 0bar :dur 1q :key 36 :vel 100)
    \\  (note :at 2q :dur 1q :key 36 :vel 80))
    \\
;

/// The document, loaded and derived — what every builder below starts
/// from.
const Ready = struct {
    schema: tempura.Schema,
    loaded: tempura.doc.Result,
    derived: tempura.time.derive.Derived,

    fn init(gpa: Allocator) !Ready {
        var schema = try tempura.Schema.load(gpa);
        errdefer schema.deinit();
        var loaded = try tempura.doc.fromSource(gpa, &schema, residue_doc, null);
        errdefer loaded.deinit();
        if (loaded.diags.hasErrors()) return Error.FixtureWriterRefused;
        const derived = try tempura.time.derive.derive(gpa, &loaded.doc);
        return .{ .schema = schema, .loaded = loaded, .derived = derived };
    }

    fn deinit(self: *Ready) void {
        self.derived.deinit();
        self.loaded.deinit();
        self.schema.deinit();
    }
};

/// `residue_doc` built into `kind`, residue attached — plan 04's rule 2,
/// with every hash agreeing because nothing has touched the file since.
fn residueExact(gpa: Allocator, kind: tempura.doc.AnchorKind) ![]u8 {
    var r = try Ready.init(gpa);
    defer r.deinit();

    var built = try tempura.doc.pipeline.build(
        gpa,
        &r.schema,
        residue_doc,
        &r.loaded.doc,
        &r.derived,
        kind,
        .{},
    );
    defer built.deinit();
    if (built.diags.hasErrors()) return Error.FixtureWriterRefused;
    return gpa.dupe(u8, built.bytes);
}

/// `residue-smf-exact` — rule 2 in a `.mid`: the essence restores, the
/// conductor record matches and the lane record matches, so the lane
/// comes back NATIVE and the rendered events are not imported.
fn residueSmfExact(gpa: Allocator) ![]u8 {
    return residueExact(gpa, .smf);
}

/// `residue-it-exact` — the same in a `.it`, through the `TMPU` chunk
/// and the message tail.
fn residueItExact(gpa: Allocator) ![]u8 {
    return residueExact(gpa, .it);
}

/// `residue-newer-version` — rule 3: a `.it` whose `TMPU` chunk carries
/// an envelope version this build does not read, and no message tail to
/// fall back on.
///
/// Two edits, and both are needed for the rule to be the one that runs.
/// EVERY record's version byte is bumped — one record left at version 1
/// would still be read, and a chunk with records and no essence is rule
/// 4's orphan case, not rule 3. And the message TAIL is taken off,
/// because plan 04's rule 5 prefers a readable tail over a chunk this
/// build cannot parse (`residue/it.zig`, `choose`), which would make this
/// a second copy of `residue-tail-only`.
///
/// What is left is the rule: the payload stays in the file exactly as it
/// is, the timeline tier is derived, and a later `build` keeps the
/// payload and writes none of its own unless `--force-residue`.
fn residueNewerVersion(gpa: Allocator) ![]u8 {
    const bytes = try residueExact(gpa, .it);
    defer gpa.free(bytes);

    var read = try itf.read.read(gpa, bytes);
    defer read.deinit();
    const region = read.module.tmpu orelse return Error.FixtureWriterRefused;
    const payload = try gpa.dupe(u8, region.slice(bytes) orelse return Error.FixtureWriterRefused);
    defer gpa.free(payload);

    // The record framing is eight head bytes, a four-byte length and the
    // body (`residue/it.zig`, `appendRecord`); the version is the fifth.
    const head_len = 8;
    var at: usize = 0;
    var seen: usize = 0;
    while (at + head_len + 4 <= payload.len) {
        if (!std.mem.eql(u8, payload[at..][0..4], "\x7Dtem")) return Error.FixtureWriterRefused;
        if (payload[at + 4] != tempura.residue.records.version) return Error.FixtureWriterRefused;
        payload[at + 4] = tempura.residue.records.version + 1;
        const len = std.mem.readInt(u32, payload[at + head_len ..][0..4], .little);
        at += head_len + 4 + len;
        seen += 1;
    }
    // The essence, the lane record and the conductor record: a fixture
    // that quietly lost one would be a weaker case than it claims.
    if (at != payload.len or seen != 3) return Error.FixtureWriterRefused;

    var module = read.module;
    module.message = tempura.residue.it.splitMessage(module.message).human;

    var file = try itf.write.write(gpa, &module, bytes, .{ .tmpu = payload });
    defer file.deinit();
    if (file.diags.hasErrors()) return Error.FixtureWriterRefused;
    return gpa.dupe(u8, file.bytes);
}

/// `residue-corrupt` — rule 4: a `.mid` whose essence says it is part 1
/// of 2 and is the only part there is.
///
/// "A split body with a missing part" is plan 04's own example of a
/// corrupt payload, and it is the mutation a sequencer that dropped one
/// meta event would leave: the surviving bytes are perfectly well formed
/// and the essence still cannot be put back together.
fn residueCorrupt(gpa: Allocator) ![]u8 {
    const bytes = try residueExact(gpa, .smf);
    errdefer gpa.free(bytes);

    // The ESSENCE record's head, found by its kind byte — the marker
    // alone could in principle occur inside a packed body.
    var i: usize = 0;
    while (i + 8 <= bytes.len) : (i += 1) {
        if (!std.mem.eql(u8, bytes[i..][0..4], "\x7Dtem")) continue;
        if (bytes[i + 5] != 1) continue;
        // `total`, the eighth byte: one part became two.
        bytes[i + 7] = 2;
        return bytes;
    }
    return Error.FixtureWriterRefused;
}

/// The built `.mid`, with one event changed the way a DAW would have
/// changed it, and written back.
///
/// The residue rides as `sequencer-specific` meta events, so reading and
/// re-writing carries it through untouched — which is exactly what a
/// sequencer that respects RP-001 does, and exactly what makes the hash
/// disagree afterwards.
fn editedSmf(gpa: Allocator, comptime what: enum { lane, conductor }) ![]u8 {
    const bytes = try residueExact(gpa, .smf);
    defer gpa.free(bytes);

    var read = try smf.read(gpa, bytes);
    defer read.deinit();

    var touched = false;
    for (read.sequence.tracks) |track| {
        for (track.events) |*e| {
            switch (what) {
                // A quantiser moved the second note: its velocity is the
                // smallest field a hash still sees.
                .lane => if (e.kind == .note_on and e.payload.note.vel == 80) {
                    e.payload.note.vel = 64;
                    touched = true;
                },
                // Somebody dragged the tempo in the DAW: 120 became 140.
                .conductor => if (e.kind == .set_tempo) {
                    e.payload.tempo = 428_571;
                    touched = true;
                },
            }
            if (touched) break;
        }
        if (touched) break;
    }
    if (!touched) return Error.FixtureWriterRefused;

    var file = try smf.write(gpa, &read.sequence, .{});
    defer file.deinit();
    if (file.diags.hasErrors()) return Error.FixtureWriterRefused;
    return gpa.dupe(u8, file.bytes);
}

/// `residue-stale-lane` — rule 2's second branch: the conductor record
/// still matches and the LANE record does not, so the lane comes back
/// BOUND at its address and `residue_stale` names what was dropped.
fn residueStaleLane(gpa: Allocator) ![]u8 {
    return editedSmf(gpa, .lane);
}

/// `residue-stale-conductor` — the same rule on the timing context: the
/// file's tempo is not the one tempura wrote, so the FILE conducts and
/// the document comes back with `:conductor` set to the anchor.
fn residueStaleConductor(gpa: Allocator) ![]u8 {
    return editedSmf(gpa, .conductor);
}

/// `residue-tail-only` — rule 5: a `.it` with the message tail and no
/// `TMPU` chunk at all.
///
/// The tail is what survives a tracker that rewrote the module, and it
/// "carries no native content and no records, so no hash check runs and
/// every rendered lane stays bound" (plan 04, rule 5). Written by
/// rendering the document and handing the writer the tail alone.
fn residueTailOnly(gpa: Allocator) ![]u8 {
    var r = try Ready.init(gpa);
    defer r.deinit();

    var rendered = try tempura.exporter.renderIt(gpa, &r.loaded.doc, &r.derived, null, .{});
    defer rendered.deinit();
    if (rendered.diags.hasErrors()) return Error.FixtureWriterRefused;

    var tail = try tempura.residue.it.tail(gpa, &r.loaded.doc, &r.derived.map);
    defer tail.deinit(gpa);
    if (tail.diags.hasErrors()) return Error.FixtureWriterRefused;

    const human = rendered.module.message;
    const whole = try tempura.residue.it.appendTail(gpa, human, tail.bytes);
    defer gpa.free(whole);

    var file = try itf.write.write(gpa, &rendered.module, null, .{
        .message_tail = whole[human.len..],
    });
    defer file.deinit();
    if (file.diags.hasErrors()) return Error.FixtureWriterRefused;
    return gpa.dupe(u8, file.bytes);
}

// ---------------------------------------------------------------------------
// Tests — run by `zig build fixtures` before it writes anything. This
// file is rooted in `tools/` and rides no other test root, so the verb
// carries its own gate.
// ---------------------------------------------------------------------------

const t_ = std.testing;

test "gen_fixtures: the same case builds the same bytes twice" {
    // The committed bytes are the corpus's input: a generator that
    // depended on an allocator's addresses, a hash-map's order or an
    // uninitialised byte would make every golden it feeds a coin toss.
    for (cases) |c| {
        const first = try c.build(t_.allocator);
        defer t_.allocator.free(first);
        const second = try c.build(t_.allocator);
        defer t_.allocator.free(second);
        try t_.expectEqualSlices(u8, first, second);
    }
}

test "gen_fixtures: every fixture reads back with nothing fatal in it" {
    // A fixture the reader refuses is not a corpus case, it is a bug
    // that would be committed. Warnings are fine and several cases exist
    // FOR their warnings; an error-severity diagnostic is not.
    for (cases) |c| {
        const bytes = try c.build(t_.allocator);
        defer t_.allocator.free(bytes);

        if (std.mem.endsWith(u8, c.file, ".mid")) {
            var r = try smf.read(t_.allocator, bytes);
            defer r.deinit();
            try t_.expect(!r.diags.hasErrors());
            try t_.expect(r.sequence.tracks.len > 0);
        } else {
            var r = try itf.read.read(t_.allocator, bytes);
            defer r.deinit();
            try t_.expect(!r.diags.hasErrors());
            try t_.expect(r.module.patterns.len > 0);
        }
    }
}

test "gen_fixtures: the case list names each directory and file once" {
    for (cases, 0..) |c, i| {
        try t_.expect(c.name.len > 0);
        try t_.expect(std.mem.endsWith(u8, c.file, ".mid") or std.mem.endsWith(u8, c.file, ".it"));
        for (cases[i + 1 ..]) |other| {
            try t_.expect(!std.mem.eql(u8, c.name, other.name));
        }
    }
}
